package com.bananalab.lite;
import android.content.Context;import java.util.*;import java.util.regex.*;import org.json.*;
/** Source dependency impact, not a proof of behavior or complete dynamic call graph. */
final class CodeAtlas{
 static JSONObject index(Map<String,String> sources)throws Exception{return CoreBuild.index(sources,"workspace");}
 static String impact(JSONObject index,String file)throws Exception{JavaSourceEdit.filename(file);Map<String,Set<String>> reverse=new TreeMap<>();JSONArray rows=index.getJSONArray("files");boolean found=false;int methods=0;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String name=row.getString("name");found|=file.equals(name);JSONArray refs=row.getJSONArray("references");for(int j=0;j<refs.length();j++){String dependency=refs.getString(j)+".java";if(!reverse.containsKey(dependency))reverse.put(dependency,new TreeSet<String>());reverse.get(dependency).add(name);}}if(!found)throw new IllegalArgumentException("Ese archivo no está en el proyecto.");Set<String> seen=new LinkedHashSet<>();seen.add(file);Set<String> frontier=new TreeSet<>();frontier.add(file);StringBuilder out=new StringBuilder("Impacto de "+file+"\n");for(int level=1;level<=2;level++){Set<String> next=new TreeSet<>();for(String name:frontier)if(reverse.containsKey(name))for(String user:reverse.get(name))if(seen.add(user))next.add(user);out.append("Dependientes a distancia ").append(level).append(": ").append(next.isEmpty()?"ninguno":JavaCompat.join(", ",next)).append('\n');frontier=next;}return out.append("Revisá los contratos, sus pruebas y los datos persistidos antes de incorporar cambios. Son referencias de fuentes; no resuelven todas las llamadas dinámicas.").toString();}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String q=ChatLanguage.normalize(input);if(!q.matches("entiende el proyecto|analiza toda la app|comprende el proyecto")&&!q.startsWith("que depende de ")&&!q.startsWith("impacto de "))return null;try{NaturalCoding.project(c);Map<String,String> sources=JavaProject.files(c,JavaProject.working(c));String text;if(q.startsWith("impacto de ")||q.startsWith("que depende de ")){String file=input.trim().substring(q.startsWith("impacto de ")?11:15).trim();text=impact(index(sources),file);}else{int methods=0;for(String source:sources.values()){Matcher m=Pattern.compile("\\b(?:static|public|private|protected)\\s+(?:static\\s+|final\\s+)*(?:[A-Za-z0-9_<>\\[\\]]+)\\s+[A-Za-z0-9_]+\\s*\\(").matcher(source);while(m.find())methods++;}text="Proyecto actual: "+sources.size()+" archivos Java, aproximadamente "+methods+" declaraciones de métodos.\nComprensión de pedidos: UnderstandingRules / MobileCore / ScenePlanner.\nProgramación: MethodLab / ProgramLab / ProgramPlan.\nEvaluación: CapabilityBench / ProgramJudge / JavaTrialService.\nInterfaz: BananaActivity / AppJavaWorkspace.\nDatos: SceneStore / CreatorMemory / LearningJournal.\nReconstrucción: CoreBuild / DeviceApk.\nPodés pedir ‘impacto de ScenePlanner.java’ para ver dependientes. Esto es un mapa verificable del proyecto, no comprensión general de todo su comportamiento.";}return MobileCore.say(c,text,"app_ajuste");}catch(Exception e){return MobileCore.say(c,"No completé el análisis: "+AndroidRepair.summary(e),"app_ajuste");}}
}
